"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["76404"],{43804(e){e.exports=JSON.parse('{"id":"FUT-0467","slug":"mutual-fund","term":"Mutual Fund","also_known_as":[],"difficulty":"Beginner","definition":"A mutual fund is an investment fund that pools money from many investors and invests it in a diversified portfolio of shares, bonds or other assets, managed by professionals.","explanation":["Instead of buying individual shares or bonds, investors buy units or shares of the fund. Each unit represents a slice of the whole portfolio. If the portfolio rises in value, so does each unit.","Mutual funds give individual investors easy access to diversification and professional management, even with small amounts of money. A single fund might hold hundreds of different companies across many industries.","Funds have different objectives. Some aim for growth, others for income, and some for a balance. Active funds employ managers who choose investments to try to beat a benchmark. Index funds aim simply to track a market index at low cost.","Investors in traditional mutual funds buy and sell units directly with the fund, usually once a day at a price based on the value of the fund\'s holdings at the close of trading, called the net asset value.","Funds charge fees, often expressed as an annual percentage of assets, such as 0.2% or 1.5%. Over many years, the difference in fees can significantly affect returns, so comparing costs is important."],"note":"","total":1500,"prev":{"slug":"municipal-bond","term":"Municipal Bond"},"next":{"slug":"mutually-exclusive-projects","term":"Mutually Exclusive Projects"}}')}}]);